type PatchUserDataParams struct {
	CallId   string
	UserData UserDataPatch
}

// PatchUserData attach business data to a live call
//
// Merges business data into a call that is already running — an order number a backend resolved after the call arrived, a case the agent opened while talking. RFC 7386 semantics: a value replaces the key, null removes it, keys the patch does not mention are left alone. Requires the AGENT role and being a party to the call; a system integrating with this rides such a session. The whole patch applies or none of it does: if it would take the call past 32 keys the call is left exactly as it was and the answer is 409, naming the keys that would not fit. Data that moved is announced to everyone on the call as CALL_USER_DATA.
//
// Parameters:
//
//	userData: An RFC 7386 merge patch over a call's business data: a value
//	replaces the key, and null removes it. Keys the patch does not mention are
//	left alone. Setting a key to the value it already holds changes nothing and
//	is announced as nothing. The bounds are UserData's. A patch of more than 32
//	keys, or with a value over 1024 bytes of UTF-8 (bytes, not characters, which
//	is why the value schema carries no maxLength), is refused with 400
//	USER_DATA_TOO_LARGE. The bounds apply to the result too, so a patch that
//	would take the call past 32 keys is refused whole with 409 rather than
//	partly applied.
func PatchUserData(ctx context.Context, clientConfig ClientConfig, params PatchUserDataParams, opts ...RequestOption) (*UserDataResponse, error) {
	callId := params.CallId
	userData := params.UserData

	if err := ValidateUuid("callId", callId); err != nil {
		return nil, err
	}

	resp, err := DoCfg[UserDataResponse](ctx, &clientConfig, "PATCH", fmt.Sprintf("/calls/%s/user-data", EncodePathSegment(callId)), &RequestOpts{
		Body: map[string]any{
			"userData": userData,
		},
		OperationID: "PatchUserData",
		Errors:      ErrorDecoders{"400": decodeErrorData[ErrorResponse], "401": decodeErrorData[ErrorResponse], "403": decodeErrorData[ErrorResponse], "404": decodeErrorData[ErrorResponse], "409": decodeErrorData[ErrorResponse], "500": decodeErrorData[ErrorResponse]},
		Options:     opts,
	})
	if err != nil {
		return nil, err
	}
	return &resp.Data, nil
}
